from datetime import datetime, timezone


def parse_ts(text):
     """Parse ISO 8601 timestamp with Z or ±HH:MM offset, return UTC-aware datetime."""
    s = text.strip()
    if not s:
        raise ValueError("empty timestamp")
    # Normalize trailing Z to +00:00
    if s.endswith('Z') or s.endswith('z'):
        s2 = s[:-1] + '+00:00'
    else:
        s2 = s
    # Must have an offset
    if not _has_offset(s2):
        raise ValueError("timestamp must have an offset")
    dt = datetime.fromisoformat(s2)
    if dt.tzinfo is None:
        raise ValueError("timestamp must have an offset")
    return dt.astimezone(timezone.utc)


def _has_offset(s):
     # check for + or - followed by HH:MM (or HHMM) somewhere after the time part
    # find first 'T' or space separator
    i = s.find('T')
    if i == -1:
        i = s.find(' ')
    if i == -1:
        return False
    rest = s[i+1:]
     # find + or - after digits
    j = 0
     # skip time digits and optional fractional
    while j < len(rest) and (rest[j].isdigit() or rest[j] in '.:'):
        j += 1
    if j < len(rest) and rest[j] in '+-':
        return True
    return False


def day_bucket(text):
     """UTC calendar day of a timestamp as YYYY-MM-DD."""
    return parse_ts(text).strftime("%Y-%m-%d")
